// ============================================================
// NODO 4 - PROCESAR INTERACCIÓN
// ============================================================

// Datos actuales
const inputData = $input.item.json || {};

// ============================================================
// RECUPERAR DATOS DE TELEGRAM
// ============================================================

// Intentamos obtener datos del nodo 1
const telegramData = $('1. Normalizar Entrada Telegram').item.json;

// ============================================================
// DATOS DE TELEGRAM
// ============================================================

const chatId = String(
  telegramData.chatId ||
  inputData.chatId ||
  inputData.telegram_id ||
  ''
);

let text = String(
  telegramData.text ||
  inputData.text ||
  ''
).trim();

const callbackData = String(
  telegramData.callbackData ||
  inputData.callbackData ||
  ''
).trim();

const callbackQueryId = String(
  telegramData.callbackQueryId ||
  inputData.callbackQueryId ||
  ''
).trim();

const userName = String(
  telegramData.userName ||
  inputData.userName ||
  ''
).trim();

const interactionType = String(
  telegramData.interactionType ||
  inputData.interactionType ||
  'unknown'
);

// ============================================================
// NORMALIZAR /START
// ============================================================

if (
  text === '/start' ||
  text === '/start@DeliveryBot' ||
  text === '/start@n8ncampuslands_bot'
) {
  text = 'start';
}

// ============================================================
// CREAR / RECUPERAR SESIÓN
// ============================================================

const session = {

  telegram_id: String(
    inputData.telegram_id ||
    telegramData.telegram_id ||
    chatId
  ),

  pantalla_actual:
    inputData.pantalla_actual ||
    'inicio',

  carrito_temporal:
    inputData.carrito_temporal ||
    '[]',

  ultimo_cambio:
    inputData.ultimo_cambio ||
    new Date().toISOString(),

  categoria_seleccionada:
    inputData.categoria_seleccionada ||
    '',

  ultimo_producto_visto:
    inputData.ultimo_producto_visto ||
    '',

  nota_temporal:
    inputData.nota_temporal ||
    ''

};

// ============================================================
// DEBUG
// ============================================================

console.log('==============================');
console.log('NODO 4 - PROCESAR INTERACCIÓN');
console.log('chatId:', chatId);
console.log('text:', text);
console.log('callbackData:', callbackData);
console.log('callbackQueryId:', callbackQueryId);
console.log('interactionType:', interactionType);
console.log('session:', session);
console.log('==============================');

// ============================================================
// DEVOLVER DATOS
// ============================================================

return {
  json: {

    ...inputData,

    chatId,

    telegram_id: session.telegram_id,

    text,

    callbackData,

    callbackQueryId,

    userName,

    interactionType,

    session

  }
};

// Obtener los datos del item actual
const data = $json;

// Buscar el telegram_id en diferentes lugares posibles
const telegram_id =
  data.telegram_id ??
  data.session?.telegram_id ??
  data.callback_query?.from?.id ??
  data.callbackQuery?.from?.id ??
  data.callback_query?.message?.chat?.id ??
  data.callbackQuery?.message?.chat?.id ??
  data.message?.chat?.id ??
  data.chat?.id;

// Validar que exista telegram_id
if (!telegram_id) {
  throw new Error(
    'No se encontró telegram_id. Datos recibidos: ' +
    JSON.stringify(data)
  );
}

// Obtener la categoría seleccionada
const categoria =
  data.categoria ??
  data.category ??
  data.callback_query?.data ??
  data.callbackQuery?.data ??
  '';

// Devolver los datos correctamente
return {
  json: {
    ...data,
    telegram_id: String(telegram_id),
    categoria: categoria
  }
};

// ============================================================
// NODO 9: CONSTRUIR MENSAJE BASE
// ============================================================

// 1. OBTENER DATOS DE ENTRADA
const data = $input.item.json || {};

const session = data.session || {};
const chatId = String(data.chatId || '');
const text = String(data.text || '');
const callbackData = String(data.callbackData || '');
const interactionType = String(data.interactionType || '');

// ============================================================
// 2. DETERMINAR LA ACCIÓN
// ============================================================

let action = 'inicio';

if (text === '/start' || text === 'start') {
  action = 'inicio';
}

else if (callbackData) {

  switch (callbackData) {

    case 'inicio':
      action = 'inicio';
      break;

    case 'menu_categoria':
      action = 'mostrar_categorias';
      break;

    case 'historial':
      action = 'mostrar_historial';
      break;

    case 'seguimiento':
      action = 'mostrar_seguimiento';
      break;

    case 'ayuda':
      action = 'mostrar_ayuda';
      break;

    case 'ver_puntos':
      action = 'ver_puntos';
      break;

    case 'ver_carrito':
      action = 'mostrar_carrito';
      break;

    case 'vaciar_carrito':
      action = 'carrito_vaciado';
      break;

    case 'confirmar_pedido':
      action = 'confirmar_pedido';
      break;

    case 'agregar_nota':
      action = 'solicitar_nota';
      break;

    case 'saltar_nota':
      action = 'confirmar_pedido';
      break;

    case 'confirmar_pago':
      action = 'procesar_pedido';
      break;

    default:

      if (callbackData.startsWith('categoria_')) {

        const categoria = callbackData.replace(
          'categoria_',
          ''
        );

        session.categoria_seleccionada = categoria;

        action = 'mostrar_productos';

      }

      else if (callbackData.startsWith('producto_')) {

        const productoId = callbackData.replace(
          'producto_',
          ''
        );

        session.ultimo_producto_visto = productoId;

        action = 'mostrar_detalle';

      }

      else if (callbackData.startsWith('agregar_carrito_')) {

        const productoId = callbackData.replace(
          'agregar_carrito_',
          ''
        );

        session.ultimo_producto_visto = productoId;

        action = 'seleccionar_cantidad';

      }

      else if (callbackData.startsWith('cantidad_')) {

        const cantidad = Number(
          callbackData.replace('cantidad_', '')
        );

        data.cantidadSeleccionada = cantidad;

        action = 'agregar_producto_carrito';

      }

      else if (callbackData.startsWith('detalle_producto_')) {

        const productoId = callbackData.replace(
          'detalle_producto_',
          ''
        );

        session.ultimo_producto_visto = productoId;

        action = 'mostrar_detalle';

      }

      else {

        action = 'inicio';

      }

      break;
  }

}

// ============================================================
// 3. VARIABLES DEL MENSAJE
// ============================================================

let messageText = '';
let keyboard = [];
let parseMode = 'HTML';

// ============================================================
// 4. MENÚ PRINCIPAL
// ============================================================

if (action === 'inicio') {

  messageText =
    '☕ <b>¡Bienvenido a DeliveryBot!</b>\n\n' +
    'Tu cafetería inteligente en Telegram.\n\n' +
    '¿Qué deseas hacer hoy?';

  keyboard = [

    [
      {
        text: '📋 Ver Menú',
        callback_data: 'menu_categoria'
      }
    ],

    [
      {
        text: '📦 Historial',
        callback_data: 'historial'
      },
      {
        text: '📍 Seguimiento',
        callback_data: 'seguimiento'
      }
    ],

    [
      {
        text: 'ℹ️ Ayuda',
        callback_data: 'ayuda'
      }
    ],

    [
      {
        text: '🏆 Ver mis puntos',
        callback_data: 'ver_puntos'
      }
    ]

  ];

}

// ============================================================
// 5. MOSTRAR CATEGORÍAS
// ============================================================

else if (action === 'mostrar_categorias') {

  messageText =
    '📋 <b>Categorías del Menú</b>\n\n' +
    'Selecciona una categoría para explorar nuestros productos.';

  keyboard = [

    [
      {
        text: '☕ Café',
        callback_data: 'categoria_cafe'
      }
    ],

    [
      {
        text: '🥐 Panadería',
        callback_data: 'categoria_panaderia'
      }
    ],

    [
      {
        text: '🍰 Postres',
        callback_data: 'categoria_postres'
      }
    ],

    [
      {
        text: '🔙 Volver',
        callback_data: 'inicio'
      }
    ]

  ];

}

// ============================================================
// 6. VER PUNTOS
// ============================================================

else if (action === 'ver_puntos') {

  messageText =
    '🏆 Consultando tus puntos acumulados...';

  keyboard = [

    [
      {
        text: '🏠 Inicio',
        callback_data: 'inicio'
      }
    ]

  ];

}

// ============================================================

 // ============================================================
// MOSTRAR PRODUCTOS
// ============================================================

else if (action === 'mostrar_productos') {

    const productos = $input.all();

    messageText =
        '🥤 <b>Productos disponibles</b>\n\nSelecciona uno:';

    keyboard = [];

    for (const item of productos) {

        const p = item.json;

        keyboard.push([
            {
                text: `${p.nombre} - $${Number(p.precio).toLocaleString('es-CO')}`,
                callback_data: `producto_${p.id_producto}`
            }
        ]);

    }

    keyboard.push([
        {
            text: '🔙 Volver',
            callback_data: 'menu_categoria'
        }
    ]);

    keyboard.push([
        {
            text: '🛒 Ver carrito',
            callback_data: 'ver_carrito'
        }
    ]);

}

// ============================================================
// HISTORIAL
// ============================================================

else if (action === 'mostrar_historial') {

  messageText =
    '📦 <b>Historial de Pedidos</b>\n\n' +
    'Cargando tu historial...';

  keyboard = [

    [
      {
        text: '🏠 Inicio',
        callback_data: 'inicio'
      }
    ]

  ];

}

// ============================================================
// SEGUIMIENTO
// ============================================================

else if (action === 'mostrar_seguimiento') {

  messageText =
    '📍 <b>Seguimiento de Pedidos</b>\n\n' +
    'Cargando el estado de tus pedidos...';

  keyboard = [

    [
      {
        text: '🔄 Actualizar',
        callback_data: 'seguimiento'
      },
      {
        text: '🏠 Inicio',
        callback_data: 'inicio'
      }
    ]

  ];

}

// ============================================================
// AYUDA
// ============================================================

else if (action === 'mostrar_ayuda') {

  messageText =
    'ℹ️ <b>Ayuda de DeliveryBot</b>\n\n' +
    '📋 <b>¿Cómo hacer un pedido?</b>\n' +
    '1. Ve al menú\n' +
    '2. Selecciona una categoría\n' +
    '3. Elige un producto\n' +
    '4. Selecciona la cantidad\n' +
    '5. Confirma tu pedido';

  keyboard = [

    [
      {
        text: '📋 Ver Menú',
        callback_data: 'menu_categoria'
      }
    ],

    [
      {
        text: '🏠 Inicio',
        callback_data: 'inicio'
      }
    ]

  ];

}

// ============================================================
// MOSTRAR CARRITO
// ============================================================

else if (
  action === 'mostrar_carrito' ||
  action === 'carrito_actualizado' ||
  action === 'agregar_producto_carrito'
) {

  let items = [];

  try {

    if (
      session.carrito_temporal &&
      session.carrito_temporal !== 'cero'
    ) {

      items = JSON.parse(session.carrito_temporal);

    }

  } catch (error) {

    items = [];

  }

  if (items.length === 0) {

    messageText =
      '🛒 <b>Tu carrito está vacío</b>\n\n' +
      'Agrega productos desde el menú.';

    keyboard = [

      [
        {
          text: '📋 Ver Menú',
          callback_data: 'menu_categoria'
        }
      ],

      [
        {
          text: '🏠 Inicio',
          callback_data: 'inicio'
        }
      ]

    ];

  } else {

    let detalle = '';
    let total = 0;

    items.forEach((item, index) => {

      const cantidad = Number(item.cantidad || 0);
      const precio = Number(item.precio || 0);

      const subtotal = cantidad * precio;

      total += subtotal;

      detalle +=
        `${index + 1}. ${item.nombre} x${cantidad} = $${subtotal.toLocaleString('es-CO')}\n`;

    });

    messageText =
      '🛒 <b>Tu carrito</b>\n\n' +
      detalle +
      '\n💰 <b>TOTAL: $' +
      total.toLocaleString('es-CO') +
      '</b>\n\n' +
      '¿Qué deseas hacer?';

    keyboard = [

      [
        {
          text: '✅ Confirmar Pedido',
          callback_data: 'confirmar_pedido'
        }
      ],

      [
        {
          text: '📋 Seguir Comprando',
          callback_data: 'menu_categoria'
        }
      ],

      [
        {
          text: '🏠 Inicio',
          callback_data: 'inicio'
        }
      ]

    ];

  }

}

// ============================================================
// CONFIRMAR PEDIDO
// ============================================================

else if (action === 'confirmar_pedido') {

  messageText =
    '📋 <b>Confirmación de Pedido</b>\n\n' +
    '¿Deseas confirmar tu pedido?';

  keyboard = [

    [
      {
        text: '✅ Confirmar y Pagar',
        callback_data: 'confirmar_pago'
      }
    ],

    [
      {
        text: '🔙 Volver al Carrito',
        callback_data: 'ver_carrito'
      }
    ],

    [
      {
        text: '🏠 Inicio',
        callback_data: 'inicio'
      }
    ]

  ];

}

// ============================================================
// PROCESAR PEDIDO
// ============================================================

else if (action === 'procesar_pedido') {

  messageText =
    '⏳ <b>Procesando tu pedido...</b>\n\n' +
    'Espera un momento.';

  keyboard = [];

}


// ============================================================
// 11. PROCESAR PEDIDO
// ============================================================

else if (action === 'procesar_pedido') {

  messageText =
    '⏳ <b>Procesando tu pedido...</b>\n\n' +
    'Espera un momento.';

  keyboard = [];

}
// ============================================================
// VER MIS PUNTOS
// ============================================================

else if (callbackData === 'ver_puntos') {

  action = 'ver_puntos';

  text =
    '🏆 Consultando tus puntos...';

}

// ============================================================
// VALOR POR DEFECTO
// ============================================================

else {

  action = 'inicio';

  text =
    '☕ <b>¡Bienvenido a DeliveryBot!</b>\n\n' +
    'Tu cafetería inteligente en Telegram.\n\n' +
    '¿Qué deseas hacer hoy?';

}

// ============================================================
// BOTONES DEL MENÚ PRINCIPAL
// ============================================================

const replyMarkup = {

  inline_keyboard: [

    [
      {
        text: '📋 Ver Menú',
        callback_data: 'menu_categoria'
      }
    ],

    [
      {
        text: '📦 Historial',
        callback_data: 'historial'
      },
      {
        text: '📍 Seguimiento',
        callback_data: 'seguimiento'
      }
    ],

    [
      {
        text: 'ℹ️ Ayuda',
        callback_data: 'ayuda'
      }
    ],

    [
      {
        text: '🏆 Ver mis puntos',
        callback_data: 'ver_puntos'
      }
    ]

  ]

};

// ============================================================
// DEVOLVER DATOS
// ============================================================

return {

  json: {

    ...$json,

    action,

    text,

    replyMarkup,

    payload: {

      chat_id: chatId,

      text,

      parse_mode: 'HTML',

      reply_markup: replyMarkup

    }

  }

};

// ============================================================
// NODO 12 - FORMATEAR CATEGORÍAS EN TECLADO
// MODO: RUN ONCE FOR ALL ITEMS
// ============================================================

// Obtener TODAS las filas que vienen del Nodo 11
const items = $input.all();

// Crear conjunto para evitar categorías repetidas
const categoriasSet = new Set();

// Recorrer todas las filas
for (const item of items) {

  const row = item.json;

  const categoria = String(
    row.categoria || ''
  ).trim();

  if (categoria) {
    categoriasSet.add(categoria);
  }
}

// Convertir Set en Array
const categorias = Array.from(categoriasSet);

// Crear teclado
const keyboard = [];

// Crear un botón por categoría
for (const categoria of categorias) {

  keyboard.push([
    {
      text: '📂 ' + categoria,
      callback_data: 'categoria_' + categoria
    }
  ]);

}

// Botones inferiores
keyboard.push([
  {
    text: '🛒 Ver Carrito',
    callback_data: 'ver_carrito'
  },
  {
    text: '🏠 Inicio',
    callback_data: 'inicio'
  }
]);

// Obtener los datos originales del primer item
const firstItem = items[0]?.json || {};

const chatId = String(
  $('9. Construir Mensaje Base').item.json.chatId || ''
);

const payload = {
  chat_id: chatId,

  text:
    '📋 <b>Categorías del Menú</b>\n\n' +
    'Selecciona una categoría para explorar nuestros productos.',

  parse_mode: 'HTML',

  reply_markup: JSON.stringify({
    inline_keyboard: keyboard
  })
};

// Devolver UN SOLO ITEM
return [
  {
    json: {
      ...firstItem,

      chatId: chatId,

      text:
        '📋 <b>Categorías del Menú</b>\n\n' +
        'Selecciona una categoría para explorar nuestros productos.',

      replyMarkup: {
        inline_keyboard: keyboard
      },

      payload: {
        chat_id: chatId,
        text:
          '📋 <b>Categorías del Menú</b>\n\n' +
          'Selecciona una categoría para explorar nuestros productos.',
        parse_mode: 'HTML',
        reply_markup: {
          inline_keyboard: keyboard
        }
      },

      needsCategories: true,
      needsProducts: false,
      needsProductDetail: false,
      isConfirmPedido: false
    }
  }
];

// Obtener todas las filas provenientes del Nodo 14
const items = $input.all();

console.log('Productos recibidos:', items.length);

// ============================================================
// OBTENER DATOS ORIGINALES
// ============================================================

const baseData = $('9. Construir Mensaje Base').item.json;

const chatId = String(
  baseData.chatId || ''
);

const session = baseData.session || {};

const categoria = String(
  session.categoria_seleccionada || ''
).trim();

// ============================================================
// VALIDAR CHAT ID
// ============================================================

if (!chatId) {
  throw new Error(
    'Nodo 15: No se encontró chatId.'
  );
}

// ============================================================
// CREAR TECLADO
// ============================================================

const keyboard = [];

// ============================================================
// RECORRER PRODUCTOS
// ============================================================

for (const item of items) {

  const product = item.json || {};

  const nombre = String(
    product.nombre || ''
  ).trim();

  const precio = Number(
    product.precio || 0
  );

  const id = String(
    product.id_producto || ''
  ).trim();

  // Ignorar filas incompletas
  if (!nombre || !id) {
    continue;
  }

  keyboard.push([
    {
      text:
        '🍽️ ' +
        nombre +
        ' - $' +
        precio.toLocaleString('es-CO'),

      callback_data:
        'producto_' + id
    }
  ]);
}

// ============================================================
// SI NO HAY PRODUCTOS
// ============================================================

let messageText = '';

if (keyboard.length === 0) {

  messageText =
    '⚠️ <b>No hay productos disponibles</b>\\n\\n' +
    'No encontramos productos para esta categoría.';

} else {

  messageText =
    '🍽️ <b>Productos disponibles</b>\\n\\n' +
    'Categoría: <b>' +
    categoria +
    '</b>\\n\\n' +
    'Selecciona un producto:';

}

// ============================================================
// BOTONES DE NAVEGACIÓN
// ============================================================

keyboard.push([
  {
    text: '🔙 Volver a Categorías',
    callback_data: 'menu_categoria'
  },
  {
    text: '🛒 Ver Carrito',
    callback_data: 'ver_carrito'
  }
]);

keyboard.push([
  {
    text: '🏠 Inicio',
    callback_data: 'inicio'
  }
]);

// ============================================================
// CREAR PAYLOAD
// ============================================================

const payload = {

  chat_id: chatId,

  text: messageText,

  parse_mode: 'HTML',

  reply_markup: {
    inline_keyboard: keyboard
  }

};

// ============================================================
// DEVOLVER RESULTADO
// ============================================================

return [
  {
    json: {

    ...baseData,

      chatId: chatId,

      session: session,

      action: 'mostrar_productos',

      needsCategories: false,

      needsProducts: true,

      needsProductDetail: false,

      isConfirmPedido: false,

      payload: payload

    }
  }
];

// ============================================================
// NODO 18 - FORMATEAR DETALLE DEL PRODUCTO
// ============================================================
// Este nodo recibe el producto encontrado desde Google Sheets
// y construye:
// - text
// - replyMarkup
// - payload
//
// IMPORTANTE:
// Se mantienen chatId, session y el resto de datos recibidos.
// ============================================================


// ============================================================
// 1. OBTENER DATOS DE ENTRADA
// ============================================================

const data = $input.item.json || {};

const product = data;


// ============================================================
// 2. SI NO SE ENCUENTRA EL PRODUCTO
// ============================================================

if (!product) {

  const text = '⚠️ <b>Producto no encontrado</b>';

  const replyMarkup = {
    inline_keyboard: [
      [
        {
          text: '🔙 Volver a Categorías',
          callback_data: 'menu_categoria'
        },
        {
          text: '🏠 Inicio',
          callback_data: 'inicio'
        }
      ]
    ]
  };

  return {
    json: {

      // Mantener todos los datos anteriores
      ...data,

      // Datos que utilizará el nodo 25
      chatId: String(data.chatId || ''),

      text: text,

      replyMarkup: replyMarkup,

      // Payload completo
      payload: {
        chat_id: String(data.chatId || ''),
        text: text,
        parse_mode: 'HTML',
        reply_markup: replyMarkup
      }

    }
  };
}


// ============================================================
// 3. DATOS DEL PRODUCTO
// ============================================================

const nombre = String(
  product.nombre || 'Producto'
);

const descripcion = String(
  product.descripcion || 'Sin descripción'
);

const precio = Number(
  product.precio || 0
);

const stock = Number(
  product.stock || 0
);

const id = String(
  product.id_producto || ''
);


// ============================================================
// 4. CREAR TEXTO DEL MENSAJE
// ============================================================

const messageText =

  '🍽️ <b>' + nombre + '</b>\n\n' +

  '📝 <b>Descripción:</b> ' +
  descripcion + '\n' +

  '💰 <b>Precio:</b> $' +
  precio.toLocaleString('es-CO') + '\n' +

  '📦 <b>Stock disponible:</b> ' +
  stock +
  ' unidades\n\n' +

  '¿Qué deseas hacer?';


// ============================================================
// 5. CREAR TECLADO INLINE
// ============================================================

const categoriaActual = String(
  data.session?.categoria_seleccionada || ''
);

const keyboard = [

  [
    {
      text: '➕ Agregar al Carrito',
      callback_data: 'agregar_carrito_' + id
    }
  ],

  [
    {
      text: '🔙 Volver a Productos',
