// ============================================================
// NODO 1 - NORMALIZAR ENTRADA TELEGRAM
// ============================================================
// Este nodo recibe cualquier actualización de Telegram:
// - Mensaje de texto
// - Callback de un botón inline
//
// Su objetivo es convertir ambos formatos en una estructura
// uniforme que el resto del workflow pueda utilizar.
// ============================================================

const input = $input.item.json;

// ============================================================
// VARIABLES BASE
// ============================================================

let interactionType = 'unknown';

let chatId = '';
let text = '';
let callbackData = '';
let callbackQueryId = '';
let userName = '';

// ============================================================
// CASO 1: MENSAJE NORMAL DE TELEGRAM
// ============================================================

if (input.message) {

  interactionType = 'message';

  chatId = String(
    input.message.chat?.id || ''
  );

  text = String(
    input.message.text || ''
  ).trim();

  userName = String(
    input.message.from?.first_name || ''
  ).trim();

}

// ============================================================
// CASO 2: BOTÓN INLINE / CALLBACK QUERY
// ============================================================

else if (input.callback_query) {

  interactionType = 'callback';

  chatId = String(
    input.callback_query.message?.chat?.id || ''
  );

  callbackData = String(
    input.callback_query.data || ''
  ).trim();

  callbackQueryId = String(
    input.callback_query.id || ''
  ).trim();

  userName = String(
    input.callback_query.from?.first_name || ''
  ).trim();

}

// ============================================================
// VALIDACIÓN
// ============================================================

if (!chatId) {

  throw new Error(
    'No se pudo obtener el chatId de Telegram.'
  );

}

// ============================================================
// DEVOLVER DATOS NORMALIZADOS
// ============================================================

return {
  json: {

    chatId,

    // El telegram_id será siempre el mismo valor que chatId
    telegram_id: chatId,

    text,

    callbackData,

    callbackQueryId,

    userName,

    interactionType,

    // Guardamos el objeto original por si necesitamos
    // información adicional posteriormente.
    raw: input

  }
};

